const i=t=>t==null?"—":Number(t).toLocaleString("en-US");function a(t){return t=Number(t)||0,t>=1e9?(t/1e9).toFixed(2)+"B":t>=1e6?(t/1e6).toFixed(2)+"M":t>=1e3?(t/1e3).toFixed(1)+"k":String(t)}function u(t){t=Number(t)||0;const r=["B","KB","MB","GB","TB"];let e=0;for(;t>=1024&&e<r.length-1;)t/=1024,e++;return(e===0?t:t.toFixed(1))+" "+r[e]}const m=t=>u((Number(t)||0)*1024);function f(t){t=Number(t)||0;const r=Math.floor(t/86400),e=Math.floor(t%86400/3600),o=Math.floor(t%3600/60);return r>0?`${r}天 ${e}小时`:e>0?`${e}小时 ${o}分`:`${o}分`}const n=t=>String(t).padStart(2,"0");function s(t){if(!t)return"";const r=new Date(Number(t)*1e3);return`${n(r.getHours())}:${n(r.getMinutes())}`}function l(t){if(!t)return"—";const r=new Date(Number(t)*1e3);return`${n(r.getMonth()+1)}-${n(r.getDate())} ${n(r.getHours())}:${n(r.getMinutes())}`}function M(t){if(!t)return"—";const r=Math.floor(Date.now()/1e3)-Number(t);return r<0?"in "+f(-r):r<60?r+"秒前":r<3600?Math.floor(r/60)+"分钟前":r<86400?Math.floor(r/3600)+"小时前":Math.floor(r/86400)+"天前"}export{a,M as b,l as c,m as d,u as e,i as f,f as g,s as h};
